-- Spawned creatures that cast spells on live but have no AI on the realm, so they only melee.
-- 2026_11_28_102_world_everlake_missing_mob_spells.sql: written by hand, not tried in game (2026-11-28).
--
-- A creature with no AIName and no ScriptName gets AggressorAI (CreatureAISelector), which only attacks in melee.
-- Checked: every spawned creature (9,706) against Wowhead Forever's abilities tab: 1,231 cast on live but have no AI.
-- Left out of their lists: the Dazed spells the core applies itself (1604, 5101, 13496, 15571), pet skills a hunter
-- learns by taming (classic_pet_tame_spell), two Forever townsfolk ids on hundreds of NPCs (1229741, 1229451), and every
-- id over 1,000,000. What is left is cast by other creatures' SmartAI on the realm; each spell gets the realm's most used
-- row for it (event, timers, chance, flags, target), when at least two creatures use that row and it needs no phase or
-- link. Critters and companion pets are left out, and creatures with more than four spells (Grimtooth, Donal Osgood, the
-- Alterac Valley Seasoned Warrior and Champion Sentinel, the Booty Bay Elite: Wowhead folds several creatures' casts into
-- one page there).
-- Here: 229 creatures, 317 rows. Most: Shoot (22 riflemen and archers), Strike (17), Poison (11), Enrage at 30% (10),
-- Shadow Bolt (10), Sneak on spawn (9), Lightning Bolt, Thrash, Frost Armor, Shield Bash on a caster. Many are Forever's own
-- creatures (Hyjal's bears and stags, the Wormwing harpies, Legashi demons, Shadowvale, Blackthorne, Razormane).
-- Rows only go in for a creature that still has no AIName, no ScriptName and no SmartAI rows of its own; a spell already
-- among its template auras is left out. The creature's AIName becomes SmartAI. Every added row and every changed
-- creature is recorded in everlake_import_rows. Never edit this file once it is deployed: a later fix is a new file.
-- Running it again changes nothing.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added';
SET @EVERLAKE_FILE := '2026_11_28_102_world_everlake_missing_mob_spells.sql';

START TRANSACTION;

-- entry, row id, event type, phase mask, chance, event flags, event params 1-5, spell, cast flags, triggered flags,
-- target type, target params 1-3 (copied from the realm's most used SmartAI row for that spell)
DROP TEMPORARY TABLE IF EXISTS `everlake_msp`;
CREATE TEMPORARY TABLE `everlake_msp` (`entry` INT UNSIGNED NOT NULL, `rid` SMALLINT UNSIGNED NOT NULL, `ev` TINYINT UNSIGNED NOT NULL,
  `phase` SMALLINT UNSIGNED NOT NULL, `chance` TINYINT UNSIGNED NOT NULL, `eflags` SMALLINT UNSIGNED NOT NULL, `e1` INT UNSIGNED NOT NULL,
  `e2` INT UNSIGNED NOT NULL, `e3` INT UNSIGNED NOT NULL, `e4` INT UNSIGNED NOT NULL, `e5` INT UNSIGNED NOT NULL, `spell` INT UNSIGNED NOT NULL,
  `a2` INT UNSIGNED NOT NULL, `a3` INT UNSIGNED NOT NULL, `tt` TINYINT UNSIGNED NOT NULL, `t1` INT UNSIGNED NOT NULL, `t2` INT UNSIGNED NOT NULL,
  `t3` INT UNSIGNED NOT NULL, `ok` TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (`entry`, `rid`));

UPDATE `everlake_msp` m JOIN `creature_template` c ON c.`entry` = m.`entry` SET m.`ok` = 1
WHERE IFNULL(c.`AIName`, '') = '' AND IFNULL(c.`ScriptName`, '') = ''
  AND NOT EXISTS (SELECT 1 FROM `smart_scripts` s WHERE s.`entryorguid` = m.`entry` AND s.`source_type` = 0)
  AND NOT EXISTS (SELECT 1 FROM `creature_template_addon` a WHERE a.`entry` = m.`entry`
                    AND FIND_IN_SET(m.`spell`, REPLACE(TRIM(IFNULL(a.`auras`, '')), ' ', ',')) > 0);

    `event_flags`, `event_param1`, `event_param2`, `event_param3`, `event_param4`, `event_param5`, `event_param_string`, `action_type`,
    `action_param1`, `action_param2`, `action_param3`, `action_param4`, `action_param5`, `action_param6`, `action_param7`,
    `action_param_string`, `target_type`, `target_param1`, `target_param2`, `target_param3`, `target_param4`, `target_param_string`,
    `target_x`, `target_y`, `target_z`, `target_o`, `comment`)
SELECT m.`entry`, 0, m.`rid`, 0, '', m.`ev`, m.`phase`, m.`chance`, m.`eflags`, m.`e1`, m.`e2`, m.`e3`, m.`e4`, m.`e5`, '', 11,
       m.`spell`, m.`a2`, m.`a3`, 0, 0, 0, 0, '', m.`tt`, m.`t1`, m.`t2`, m.`t3`, 0, '', 0, 0, 0, 0,
       CONCAT('Everlake: cast ', m.`spell`, ' (Wowhead Forever abilities; timing as the realm''s other casters)')
FROM `everlake_msp` m WHERE m.`ok` = 1;
SELECT 'smart_scripts', m.`entry`, 0, m.`rid`, 0, @EVERLAKE_FILE, CONCAT('cast ', m.`spell`, ' (Wowhead Forever abilities)')
FROM `everlake_msp` m WHERE m.`ok` = 1;
SELECT DISTINCT 'creature_template', m.`entry`, 0, 0, 102, @EVERLAKE_FILE, 'AIName '''' -> SmartAI (its live spells)'
FROM `everlake_msp` m WHERE m.`ok` = 1;
UPDATE `creature_template` c JOIN (SELECT DISTINCT `entry` FROM `everlake_msp` WHERE `ok` = 1) m ON m.`entry` = c.`entry`
SET c.`AIName` = 'SmartAI' WHERE IFNULL(c.`AIName`, '') = '' AND IFNULL(c.`ScriptName`, '') = '';
DROP TEMPORARY TABLE `everlake_msp`;

COMMIT;
